{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C09"],
      "claim": "Acamprosate, a small polar molecule with an acidic sulfonate and amide, has a measured absolute oral bioavailability of only 11±1% in healthy volunteers after oral vs IV dosing; its high assay-transfer score and shared ionizable polar functionality support low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C51"],
      "claim": "Oseltamivir carboxylate, the free carboxylate form, shows <5% oral bioavailability in humans when given orally, directly demonstrating that a highly polar amino-acid-like carboxylate is poorly absorbed; this is directly relevant to the query's multiple free carboxylic acids.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Tetrahydrouridine, a polar nucleoside with multiple hydroxyl and amide H-bond donors, has a human bioavailability of only 4.1%, supporting low oral absorption for the peptide-like, H-bond-rich query scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Ferulic acid, a small phenolic carboxylic acid, has only 3-10% oral bioavailability in humans, reinforcing that carboxylic-acid-containing polar molecules tend to have low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C44"],
      "claim": "Finasteride, a lipophilic steroid amide, has ~80% absolute oral bioavailability in healthy volunteers, but its very low transfer score and lack of shared polar/ionizable features make it a weak contradictory anchor; it does not outweigh the direct low-F analogues.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a highly polar, peptide-like diketopiperazine bearing two free carboxylic acids and multiple amide H-bond donors/acceptors. High-transfer experimental analogues with similar ionizable polar character (acamprosate 11%, oseltamivir carboxylate <5%, tetrahydrouridine 4.1%, ferulic acid 3-10%) all show low oral bioavailability, strongly supporting F<20%. The only high-F analogue (finasteride) is lipophilic and has very low transferability.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the exact diketopiperazine query molecule.",
    "Potential effects of active transport, efflux, or formulation on the query's absorption are unknown.",
    "High oral bioavailability values for oseltamivir carboxylate were obtained after administration of its ethyl-ester prodrug and do not apply to the free dicarboxylic acid form."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

